export const settingsIcon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m9 3-.5 2-2 1-2-.5-2 3 1.5 1.5v3L2.5 15l2 3 2-.5 2 1L9 21h6l.5-2.5 2-1 2 .5 2-3-1.5-2v-3l1.5-1.5-2-3-2 .5-2-1L15 3Z"/><circle cx="12" cy="12" r="3"/></svg>';
export const settingsButton=(className='hub-icon-button')=>`<button class="${className} settings-trigger" data-action="settings" aria-label="환경설정" title="환경설정">${settingsIcon}</button>`;
export const normalizeSoundVolume=value=>typeof value==='number'&&Number.isFinite(value)?Math.max(0,Math.min(100,Math.round(value))):100;
export function settingsMarkup(profile){
 return `<div class="modal-backdrop"><section class="modal settings-dialog" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="modal-close" data-action="close" aria-label="환경설정 닫기">×</button><header><span>SETTINGS</span><h2 id="modal-title">환경설정</h2></header><div class="settings-section-title">소리</div><div class="settings-row"><div><label id="sfx-label">효과음</label><small>버튼 · 카드 · 스킬 효과음</small></div><button class="settings-toggle" data-action="settings-sound" role="switch" aria-labelledby="sfx-label" aria-checked="${profile.sound}"><span>${profile.sound?'켜짐':'꺼짐'}</span><i></i></button></div><div class="settings-volume"><div><label for="sound-volume">효과음 크기</label><output for="sound-volume" id="sound-volume-value">${profile.soundVolume}%</output></div><input type="range" id="sound-volume" min="0" max="100" step="1" value="${profile.soundVolume}" ${profile.sound?'':'disabled'}><button class="settings-test" data-action="settings-test" ${profile.sound&&profile.soundVolume>0?'':'disabled'}>소리 듣기</button></div><footer><span>변경 사항은 자동으로 저장됩니다.</span><button class="settings-done" data-action="close">확인</button></footer></section></div>`;
}
